-- iterations: generated by `npm run guide:content` from content/guide/iterations.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 12,
  "outcome": "Вы замечаете, что агент свернул не туда, и быстро возвращаете его на курс: остановкой, точной поправкой, откатом или новым стартом.",
  "blocks": [
    {
      "type": "text",
      "text": "Ошибиться агент может на любом шаге. Важно не то, ошибся ли он, а как быстро вы это заметили и как поправили. Дешевле всего — в первые секунды."
    },
    {
      "type": "heading",
      "text": "Четыре способа поправить курс"
    },
    {
      "type": "list",
      "items": [
        "**Esc** — остановить сразу. Текущее действие отменится, контекст останется, и вы скажете, что не так.",
        "**Сообщение в очередь** — пишите, пока агент работает: он прочитает его, как только закончит текущий шаг.",
        "**«Отмени это»** или `/rewind` — вернуть последние правки (шаг 1.5).",
        "**`/clear` и новая постановка** — если дважды поправили, а он всё мимо (шаг 2.4)."
      ]
    },
    {
      "type": "compare",
      "before": {
        "label": "Расплывчатая поправка",
        "text": "Не то. Сделай нормально.",
        "note": "Агент не знает, что именно не так, и меняет что попало."
      },
      "after": {
